import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 34 Quick work","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 34 Quick work","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 33 Out of the darkness","link":"/life/english/new-concept/book-2/unit-02/lesson-033"},"next":{"text":"第二册：实践与进步 · Lesson 35 Stop thief!","link":"/life/english/new-concept/book-2/unit-02/lesson-035"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 33 Out of the darkness","link":"/life/english/new-concept/book-2/unit-02/lesson-033"},"next":{"text":"第二册：实践与进步 · Lesson 35 Stop thief!","link":"/life/english/new-concept/book-2/unit-02/lesson-035"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-034.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-034.md"}'),i={name:"life/english/new-concept/book-2/unit-02/lesson-034.md"};function l(r,e,s,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-34-quick-work" tabindex="-1">第二册：实践与进步 · Lesson 34 Quick work <a class="header-anchor" href="#第二册-实践与进步-·-lesson-34-quick-work" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 34 Quick work&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>物品失而复得的消息来得很快，但失窃可能发生在很久以前；练习过去发现与更早事实。本课的语言观察是：told me that it had been found 同时体现转述和过去完成被动。过去参照是通知的时刻，找回先于通知，执行者可不出现。完成学习后，请写一条失物找回通知，说明报失时间、通知内容和当前状态。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>police</td><td>/pəˈliːs/</td><td>n.</td><td>警方</td><td>call the police</td></tr><tr><td>station</td><td>/ˈsteɪʃən/</td><td>n.</td><td>车站；警察局</td><td>a police station</td></tr><tr><td>recover</td><td>/rɪˈkʌvə/</td><td>v.</td><td>找回；恢复</td><td>recover a bag</td></tr><tr><td>bicycle</td><td>/ˈbaɪsɪkəl/</td><td>n.</td><td>自行车</td><td>ride a bicycle</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at the police station — 在警察局</li><li>a long time ago — 很久以前，通常配过去时</li></ul><h2 id="语法讲解-间接引语与视角转换" tabindex="-1">语法讲解：间接引语与视角转换 <a class="header-anchor" href="#语法讲解-间接引语与视角转换" aria-label="Permalink to &quot;语法讲解：间接引语与视角转换&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：told me that it had been found 同时体现转述和过去完成被动。过去参照是通知的时刻，找回先于通知，执行者可不出现。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The police told me that my bicycle had been found.</p></blockquote><p>警方告诉我，我的自行车已被找回。</p><p>told me 引出接收信息的人；had been found 是从通知时刻回看更早找回动作的被动结构。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>police 通常作复数集合名词：The police are investigating，不用 is。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 had been found，重读 found；对照 two years earlier 与 now 的时间含义。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The police told me that my bicycle had been found. I had reported it missing two years earlier. Its bell was gone, but the frame was undamaged.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一条失物找回通知，说明报失时间、通知内容和当前状态。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：told me 引出接收信息的人；had been found 是从通知时刻回看更早找回动作的被动结构。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：police 通常作复数集合名词：The police are investigating，不用 is。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 been/being：My bicycle had ___ found.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 过去完成时被动为 had been done。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>车上什么部件不见了？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The bell.</p><p><strong>解析：</strong> 车架完好与铃铛丢失是不同事实。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>选择：The police is / are checking the bicycle.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The police are checking the bicycle.</p><p><strong>解析：</strong> police 作复数集合名词，配 are。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语与视角转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-033">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-035">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
